// Gameplay canvas only. DOM HUD, names, menus and recording controls never enter media.
export function createMediaStore(scope,{indexedDB=globalThis.indexedDB}={}){
 let opening=null;
 function db(){if(!indexedDB)return Promise.reject(Error('Gallery storage is unavailable in this browser. Export your capture instead.'));if(!opening)opening=new Promise((resolve,reject)=>{const r=indexedDB.open('city-and-us-media-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('captures',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>{opening=null;reject(r.error);};});return opening;}
 async function transact(mode,fn){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('captures',mode),store=tx.objectStore('captures');let result;tx.oncomplete=()=>resolve(result);tx.onerror=tx.onabort=()=>reject(tx.error||Error('Gallery storage failed.'));fn(store,value=>result=value,tx);});}
 return {
 list:()=>transact('readonly',(s,done)=>{s.getAll().onsuccess=e=>done(e.target.result.filter(i=>i.scope===scope).sort((a,b)=>b.created-a.created));}),
 put:blob=>transact('readwrite',(s,done,tx)=>{s.getAll().onsuccess=e=>{const all=e.target.result;if(all.length>=40||all.reduce((n,i)=>n+i.blob.size,0)+blob.size>80*1024*1024){tx.abort();return;}const item={id:globalThis.crypto.randomUUID(),scope,created:Date.now(),type:blob.type.startsWith('video/')?'video':'photo',blob};s.add(item);done(item);};}),
 delete:id=>transact('readwrite',(s,done)=>{s.get(id).onsuccess=e=>{if(e.target.result?.scope===scope)s.delete(id);done(true);};})
 };
}
export function exportCapture(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
export function createGameplayMedia({canvas,render,scope,close,toast,mediaStore=null}){
 const store=mediaStore||createMediaStore(scope);let recorder=null,stream=null,chunks=[],bytes=0,timer=null,pending=null,toolbar=null,started=0,saving=false;
 const available=()=>!!(canvas.captureStream&&globalThis.MediaRecorder);
 function extension(blob){return blob.type.startsWith('video/')?(blob.type.includes('mp4')?'mp4':'webm'):'png';}
 async function persist(blob){pending=blob;saving=true;status('Saving capture…');try{await store.put(blob);pending=null;toast('Saved in Phone → Gallery.');status('Saved to Gallery.');}catch{status('Could not save. Gallery may be full or unavailable. Export now, or delete old captures and retry.');}finally{saving=false;buttons();}}
 function status(text){if(toolbar)toolbar.querySelector('#capture-status').textContent=text;}
 function buttons(){if(!toolbar)return;toolbar.querySelector('#capture-photo').disabled=saving||!!pending||!!recorder;toolbar.querySelector('#capture-video').disabled=saving||!!pending||!available()||!!recorder;toolbar.querySelector('#capture-stop').hidden=!recorder;toolbar.querySelector('#capture-retry').hidden=!pending;toolbar.querySelector('#capture-export').hidden=!pending;toolbar.querySelector('#capture-discard').hidden=!pending;}
 function stop(){if(recorder&&recorder.state!=='inactive')recorder.stop();}
 function leave(){if(recorder){stop();status('Stopping and saving…');return;}toolbar?.remove();toolbar=null;document.body.classList.remove('capture-mode');clearInterval(timer);timer=null;}
 function open(){close();if(toolbar)return;document.body.classList.add('capture-mode');toolbar=document.createElement('aside');toolbar.id='capture-controls';toolbar.innerHTML='<strong>Gameplay camera</strong><p id="capture-status" role="status">Photos capture the game without HUD. Videos: up to 30 seconds, silent gameplay.</p><button id="capture-photo">Take photo</button><button id="capture-video">Record video</button><button id="capture-stop">Stop & save</button><button id="capture-retry">Retry save</button><button id="capture-export">Export unsaved capture</button><button id="capture-discard">Discard unsaved capture</button><button id="capture-exit">Return to game</button>';document.body.appendChild(toolbar);for(const event of ['pointerdown','pointerup','keydown'])toolbar.addEventListener(event,e=>{if(event!=='keydown'||!['Tab','Escape'].includes(e.key))e.stopPropagation?.();});
 toolbar.querySelector('#capture-photo').onclick=()=>{if(saving||pending||recorder)return;saving=true;buttons();try{render();canvas.toBlob(blob=>{if(blob)persist(blob);else{saving=false;status('Capture failed. Try again.');buttons();}},'image/png');}catch{saving=false;status('Capture failed. Try again.');buttons();}};
 toolbar.querySelector('#capture-video').onclick=()=>{if(!available()||recorder||saving)return;try{const mime=['video/webm;codecs=vp8','video/webm','video/mp4'].find(t=>MediaRecorder.isTypeSupported(t));stream=canvas.captureStream(24);recorder=new MediaRecorder(stream,{...(mime?{mimeType:mime}:{}),videoBitsPerSecond:1800000});chunks=[];bytes=0;const active=recorder;active.ondataavailable=e=>{if(e.data.size){chunks.push(e.data);bytes+=e.data.size;if(bytes>24*1024*1024)stop();}};active.onerror=()=>{status('Recording error. Saving any captured frames.');stop();};active.onstop=()=>{clearInterval(timer);timer=null;stream?.getTracks().forEach(t=>t.stop());stream=null;recorder=null;const blob=new Blob(chunks,{type:active.mimeType||'video/webm'});chunks=[];if(blob.size)persist(blob);else{status('No frames recorded. Try a photo.');buttons();}};active.start(500);started=Date.now();timer=setInterval(()=>{const seconds=Math.floor((Date.now()-started)/1000);status('● RECORDING · '+seconds+' / 30 s · Stop & save when ready');if(seconds>=30)stop();},250);buttons();status('● RECORDING · 0 / 30 s');}catch{stream?.getTracks().forEach(t=>t.stop());recorder=null;status('Video recording is unavailable here. Photos are available.');buttons();}};
 let discardConfirmed=false;toolbar.querySelector('#capture-discard').onclick=()=>{if(!discardConfirmed){discardConfirmed=true;toolbar.querySelector('#capture-discard').textContent='Confirm discard';return;}pending=null;discardConfirmed=false;buttons();status('Unsaved capture discarded.');};toolbar.querySelector('#capture-stop').onclick=stop;toolbar.querySelector('#capture-exit').onclick=leave;toolbar.querySelector('#capture-retry').onclick=()=>pending&&!saving&&persist(pending);toolbar.querySelector('#capture-export').onclick=()=>pending&&exportCapture(pending,'city-and-us-capture.'+extension(pending));buttons();if(!available())status('Video recording is not supported by this browser. Take and save photos here.');
 }
 function gallery(root){let disposed=false,urls=[];const release=()=>{urls.forEach(u=>URL.revokeObjectURL(u));urls=[];};
 async function show(){try{const items=await store.list();if(disposed)return;release();root.innerHTML='<p>Saved on this browser, for this story. Export media separately from your story backup. Up to 40 captures / 80 MB across stories.</p><button id="gallery-camera">Open camera</button><div id="gallery-items" class="gallery-items"></div>';root.querySelector('#gallery-camera').onclick=open;const host=root.querySelector('#gallery-items');if(!items.length)host.textContent='No captures yet. Take a gameplay photo.';for(const item of items){const url=URL.createObjectURL(item.blob);urls.push(url);const article=document.createElement('article'),media=document.createElement(item.type==='video'?'video':'img');media.src=url;if(item.type==='photo'){media.loading='lazy';media.decoding='async';}media.alt='Gameplay photo '+new Date(item.created).toLocaleString();if(item.type==='video'){media.controls=true;media.preload='metadata';media.playsInline=true;}article.appendChild(media);const caption=document.createElement('small');caption.textContent=new Date(item.created).toLocaleString();article.appendChild(caption);const exp=document.createElement('button');exp.textContent='Export';exp.onclick=()=>exportCapture(item.blob,'city-and-us-'+item.created+'.'+extension(item.blob));article.appendChild(exp);const del=document.createElement('button');del.textContent='Delete';let confirm=false;del.onclick=async()=>{if(!confirm){confirm=true;del.textContent='Confirm delete';return;}try{await store.delete(item.id);await show();}catch{toast('Could not delete this capture.');}};article.appendChild(del);host.appendChild(article);}}
 catch{if(!disposed)root.textContent='Gallery storage is unavailable. Camera can still export unsaved captures.';}}
 show();return {tick(){},dispose(){disposed=true;release();}};
 }
 addEventListener('pagehide',stop);addEventListener('blur',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
 return {open,gallery,stop,get recording(){return !!recorder;},get active(){return !!toolbar;}};
}
